import"./diagnostics_shared.css.js";import"./input_card.js";import"./keyboard_tester.js";import"./touchscreen_tester.js";import{loadTimeData}from"chrome://resources/ash/common/load_time_data.m.js";import{I18nMixin}from"chrome://resources/cr_elements/i18n_mixin.js";import{assert}from"chrome://resources/js/assert.js";import{afterNextRender,PolymerElement}from"chrome://resources/polymer/v3_0/polymer/polymer_bundled.min.js";import{DiagnosticsBrowserProxyImpl}from"./diagnostics_browser_proxy.js";import{ConnectionType}from"./input.mojom-webui.js";import{ConnectedDevicesObserverReceiver,InternalDisplayPowerStateObserverReceiver,LidStateObserverReceiver,TabletModeObserverReceiver,TouchDeviceType}from"./input_data_provider.mojom-webui.js";import{getTemplate}from"./input_list.html.js";import{getInputDataProvider}from"./mojo_interface_provider.js";import{TouchpadTesterElement}from"./touchpad_tester.js";const InputListElementBase=I18nMixin(PolymerElement);export class InputListElement extends InputListElementBase{static get is(){return"input-list"}static get template(){return getTemplate()}static get properties(){return{keyboards:{type:Array,value:()=>[]},touchpads:{type:Array,value:()=>[]},touchscreens:{type:Array,value:()=>[]},showTouchpads:{type:Boolean,computed:"computeShowTouchpads(touchpads.length)"},showTouchscreens:{type:Boolean,computed:"computeShowTouchscreens(touchscreens.length)"},touchscreenIdUnderTesting:{type:Number,value:-1,notify:true},hostDeviceStatus:{type:Object}}}computeShowTouchpads(numTouchpads){return numTouchpads>0&&loadTimeData.getBoolean("isTouchpadEnabled")}computeShowTouchscreens(numTouchscreens){return numTouchscreens>0&&loadTimeData.getBoolean("isTouchscreenEnabled")}constructor(){super();this.touchscreenIdUnderTesting=-1;this.hostDeviceStatus={isLidOpen:false,isTabletMode:false};this.connectedDevicesObserverReceiver=null;this.internalDisplayPowerStateObserverReceiver=null;this.tabletModeReceiver=null;this.lidStateReceiver=null;this.touchscreenTester=null;this.touchpadTester=null;this.browserProxy=DiagnosticsBrowserProxyImpl.getInstance();this.inputDataProvider=getInputDataProvider();this.browserProxy.initialize();this.loadInitialDevices();this.observeConnectedDevices();this.observeInternalDisplayPowerState();this.observeLidState();this.observeTabletMode()}connectedCallback(){super.connectedCallback();const keyboardTester=this.shadowRoot.querySelector("keyboard-tester");assert(keyboardTester);this.keyboardTester=keyboardTester}loadInitialDevices(){this.inputDataProvider.getConnectedDevices().then((devices=>{this.keyboards=devices.keyboards;this.touchpads=devices.touchDevices.filter((device=>device.type===TouchDeviceType.kPointer));this.touchscreens=devices.touchDevices.filter((device=>device.type===TouchDeviceType.kDirect))}))}observeConnectedDevices(){this.connectedDevicesObserverReceiver=new ConnectedDevicesObserverReceiver(this);this.inputDataProvider.observeConnectedDevices(this.connectedDevicesObserverReceiver.$.bindNewPipeAndPassRemote())}observeInternalDisplayPowerState(){this.internalDisplayPowerStateObserverReceiver=new InternalDisplayPowerStateObserverReceiver(this);this.inputDataProvider.observeInternalDisplayPowerState(this.internalDisplayPowerStateObserverReceiver.$.bindNewPipeAndPassRemote())}observeLidState(){this.lidStateReceiver=new LidStateObserverReceiver(this);this.inputDataProvider.observeLidState(this.lidStateReceiver.$.bindNewPipeAndPassRemote()).then((({isLidOpen:isLidOpen})=>{this.onLidStateChanged(isLidOpen)}))}observeTabletMode(){this.tabletModeReceiver=new TabletModeObserverReceiver(this);this.inputDataProvider.observeTabletMode(this.tabletModeReceiver.$.bindNewPipeAndPassRemote()).then((({isTabletMode:isTabletMode})=>{this.onTabletModeChanged(isTabletMode)}))}onInternalDisplayPowerStateChanged(isDisplayOn){const index=this.touchscreens.findIndex((device=>device.connectionType===ConnectionType.kInternal));if(index!=-1){const internalTouchscreen={...this.touchscreens[index]};internalTouchscreen.testable=isDisplayOn;this.splice("touchscreens",index,1,internalTouchscreen);if(!isDisplayOn&&internalTouchscreen.id===this.touchscreenIdUnderTesting){assert(this.touchscreenTester);this.touchscreenTester.closeTester()}}}onKeyboardConnected(newKeyboard){this.push("keyboards",newKeyboard)}removeDeviceById(path,id){const index=this.get(path).findIndex((device=>device.id===id));if(index!==-1){this.splice(path,index,1)}}showDeviceDisconnectedToast(){this.dispatchEvent(new CustomEvent("show-toast",{composed:true,bubbles:true,detail:{message:loadTimeData.getString("deviceDisconnected")}}))}onKeyboardDisconnected(id){this.removeDeviceById("keyboards",id);if(this.keyboards.length===0&&this.keyboardTester?.isOpen()){this.keyboardTester.close();this.showDeviceDisconnectedToast()}}onTouchDeviceConnected(newTouchDevice){if(newTouchDevice.type===TouchDeviceType.kPointer){this.push("touchpads",newTouchDevice)}else{this.push("touchscreens",newTouchDevice)}}onTouchDeviceDisconnected(id){this.removeDeviceById("touchpads",id);this.removeDeviceById("touchscreens",id);if(id===this.touchscreenIdUnderTesting){assert(this.touchscreenTester);this.touchscreenTester.closeTester()}}handleKeyboardTestButtonClick(e){const keyboard=this.keyboards.find((keyboard=>keyboard.id===e.detail.evdevId));assert(keyboard);this.keyboardTester.keyboard=keyboard;this.keyboardTester.show()}handleTouchpadTestButtonClick(e){this.touchpadTester=this.shadowRoot.querySelector(TouchpadTesterElement.is);assert(this.touchpadTester);const touchpad=this.touchpads.find((touchpad=>touchpad.id===e.detail.evdevId));assert(touchpad);this.touchpadTester.show(touchpad)}handleTouchscreenTestButtonClick(e){this.touchscreenTester=this.shadowRoot.querySelector("touchscreen-tester");assert(this.touchscreenTester);this.touchscreenIdUnderTesting=e.detail.evdevId;this.touchscreenTester.showTester(e.detail.evdevId)}onNavigationPageChanged({isActive:isActive}){if(isActive){afterNextRender(this,(()=>{if(this.keyboards){const keyboard=this.shadowRoot.querySelector("#keyboardInputCard");assert(keyboard);const keyboardTitle=keyboard.querySelector("#keyboardTitle");assert(keyboardTitle);keyboardTitle.focus()}else{const inputListContainer=this.shadowRoot.querySelector("#inputListContainer");assert(inputListContainer);inputListContainer.focus()}}));this.browserProxy.recordNavigation("input")}}onHostDeviceStatusChanged(){if(!this.keyboardTester.isOpen()||this.keyboardTester.keyboard.connectionType!=ConnectionType.kInternal){return}if(this.hostDeviceStatus.isLidOpen&&!this.hostDeviceStatus.isTabletMode){return}this.keyboardTester.close();this.dispatchEvent(new CustomEvent("show-toast",{composed:true,bubbles:true,detail:{message:this.getKeyboardTesterClosedToastString()}}))}getKeyboardTesterClosedToastString(){if(!this.hostDeviceStatus.isLidOpen){return loadTimeData.getString("inputKeyboardTesterClosedToastLidClosed")}if(this.hostDeviceStatus.isTabletMode){return loadTimeData.getString("inputKeyboardTesterClosedToastTabletMode")}return loadTimeData.getString("deviceDisconnected")}onTabletModeChanged(isTabletMode){this.hostDeviceStatus={...this.hostDeviceStatus,isTabletMode:isTabletMode};this.onHostDeviceStatusChanged()}onLidStateChanged(isLidOpen){this.hostDeviceStatus={...this.hostDeviceStatus,isLidOpen:isLidOpen};this.onHostDeviceStatusChanged()}}customElements.define(InputListElement.is,InputListElement);